param(
  [Parameter(Mandatory=$true)]
  [string]$XlsxPath
)

$ErrorActionPreference = "Stop"

if (!(Test-Path $XlsxPath)) { throw "File not found: $XlsxPath" }

$temp = Join-Path $env:TEMP ("webexcel_preflight_" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $temp | Out-Null

try {
  Expand-Archive -Path $XlsxPath -DestinationPath $temp -Force

  $fail = @()

  # 1) namespace-prefixed roots (STOP-SHIP)
  $workbookXml = Join-Path $temp "xl\workbook.xml"
  if (Test-Path $workbookXml) {
    $wbText = Get-Content $workbookXml -Raw
    if ($wbText -match "<ns\d+:workbook\b") { $fail += "STOP-SHIP: xl/workbook.xml has namespace-prefixed root <ns#:workbook>" }
    if ($wbText -match "xmlns:ns\d+=""http://schemas\.openxmlformats\.org/spreadsheetml/2006/main""") { $fail += "STOP-SHIP: xl/workbook.xml has generic xmlns:ns# rewrite" }
  } else {
    $fail += "Missing xl/workbook.xml (invalid package)"
  }

  $sheets = Get-ChildItem (Join-Path $temp "xl\worksheets") -Filter "sheet*.xml" -ErrorAction SilentlyContinue
  foreach ($s in $sheets) {
    $t = Get-Content $s.FullName -Raw
    if ($t -match "<ns\d+:worksheet\b") { $fail += "STOP-SHIP: $($s.Name) has namespace-prefixed root <ns#:worksheet>" }
    if ($t -match "xmlns:ns\d+=""http://schemas\.openxmlformats\.org/spreadsheetml/2006/main""") { $fail += "STOP-SHIP: $($s.Name) has generic xmlns:ns# rewrite" }
  }

  # 2) known WebExcel formula ban list (optional but recommended)
  $allXml = Get-ChildItem $temp -Recurse -Include *.xml | Select-Object -ExpandProperty FullName
  $joined = ($allXml | ForEach-Object { Get-Content $_ -Raw }) -join "`n"
  if ($joined -match "_xlfn\.") { $fail += "STOP-SHIP: found _xlfn.* in XML" }
  if ($joined -match "_xludf\.") { $fail += "STOP-SHIP: found _xludf.* in XML" }

  if ($fail.Count -gt 0) {
    $fail | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    throw "Preflight FAILED. Do not ship."
  }

  Write-Host "Preflight PASSED (no XML reserialization fingerprints found)." -ForegroundColor Green
}
finally {
  Remove-Item -Recurse -Force $temp -ErrorAction SilentlyContinue
}

