const TASKID_CFG = {
  SHEET_NAME: 'Daily Planner 2026',
  COL_DATE: 1,        // A
  COL_ACTIVITY: 4,    // D
  COL_TASKID: 20,     // T  ✅ (your sheet shows TaskID in T)
  COUNTER_KEY: 'TASK_COUNTER_2026'
};

function taskId_onEdit_(e) {
  const sh = e.range.getSheet();
  if (sh.getName() !== TASKID_CFG.SHEET_NAME) return;

  const range = e.range;
  const startRow = range.getRow();
  const startCol = range.getColumn();
  const numRows = range.getNumRows();
  const numCols = range.getNumColumns();
  if (startRow < 2) return;

  const endCol = startCol + numCols - 1;
  const touchesActivity = (startCol <= TASKID_CFG.COL_ACTIVITY && TASKID_CFG.COL_ACTIVITY <= endCol);
  if (!touchesActivity) return;

  for (let r = startRow; r < startRow + numRows; r++) {
    ensureTaskId_(sh, r);
  }
}

function ensureTaskId_(sh, row) {
  const activity = (sh.getRange(row, TASKID_CFG.COL_ACTIVITY).getValue() || '').toString().trim();
  if (!activity) return;

  const idCell = sh.getRange(row, TASKID_CFG.COL_TASKID);
  const existing = (idCell.getDisplayValue() || '').trim();
  if (existing) return;

  const dateVal = sh.getRange(row, TASKID_CFG.COL_DATE).getValue();
  const next = getNextTaskCounter_();
  const id = formatTaskId_(dateVal, next);

  idCell.setNumberFormat('@');
  idCell.setValue(id);
}

function formatTaskId_(dateVal, counter) {
  const prefix = (dateVal instanceof Date)
    ? Utilities.formatDate(dateVal, Session.getScriptTimeZone(), 'yyyyMMdd')
    : 'nodate';
  return `${prefix}-${String(counter).padStart(5, '0')}`;
}

function getNextTaskCounter_() {
  const lock = LockService.getDocumentLock();
  lock.waitLock(30000);
  try {
    const props = PropertiesService.getDocumentProperties();
    let nRaw = props.getProperty(TASKID_CFG.COUNTER_KEY);

    if (!nRaw) {
      const maxOnSheet = scanMaxCounterOnSheet_();
      props.setProperty(TASKID_CFG.COUNTER_KEY, String(maxOnSheet));
      nRaw = String(maxOnSheet);
    }

    let n = parseInt(nRaw, 10);
    if (!Number.isFinite(n) || n < 0) n = 0;

    n += 1;
    props.setProperty(TASKID_CFG.COUNTER_KEY, String(n));
    return n;
  } finally {
    lock.releaseLock();
  }
}

function scanMaxCounterOnSheet_() {
  const sh = SpreadsheetApp.getActive().getSheetByName(TASKID_CFG.SHEET_NAME);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return 0;

  const ids = sh.getRange(2, TASKID_CFG.COL_TASKID, lastRow - 1, 1).getDisplayValues().flat();
  let max = 0;
  for (const s of ids) {
    const m = (s || '').toString().match(/-(\d+)\s*$/);
    if (!m) continue;
    const n = parseInt(m[1], 10);
    if (Number.isFinite(n) && n > max) max = n;
  }
  return max;
}

// Convert current TaskID formulas -> values (stops them from mutating)
function freezeTaskIds() {
  const sh = SpreadsheetApp.getActive().getSheetByName(TASKID_CFG.SHEET_NAME);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return;

  const rng = sh.getRange(2, TASKID_CFG.COL_TASKID, lastRow - 1, 1);
  const vals = rng.getDisplayValues();
  rng.setNumberFormat('@');
  rng.setValues(vals);

  PropertiesService.getDocumentProperties()
    .setProperty(TASKID_CFG.COUNTER_KEY, String(scanMaxCounterOnSheet_()));
}

// Fill IDs for any row that has Activity but no TaskID
function backfillTaskIds() {
  const sh = SpreadsheetApp.getActive().getSheetByName(TASKID_CFG.SHEET_NAME);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return;

  PropertiesService.getDocumentProperties()
    .setProperty(TASKID_CFG.COUNTER_KEY, String(scanMaxCounterOnSheet_()));

  for (let r = 2; r <= lastRow; r++) ensureTaskId_(sh, r);
}

// Fix duplicates (e.g., someone copied rows)
function fixDuplicateTaskIds() {
  const sh = SpreadsheetApp.getActive().getSheetByName(TASKID_CFG.SHEET_NAME);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return;

  const ids = sh.getRange(2, TASKID_CFG.COL_TASKID, lastRow - 1, 1).getDisplayValues().flat();
  const seen = new Set();

  for (let i = 0; i < ids.length; i++) {
    const row = i + 2;
    const id = (ids[i] || '').toString().trim();
    const activity = (sh.getRange(row, TASKID_CFG.COL_ACTIVITY).getValue() || '').toString().trim();
    if (!activity || !id) continue;

    if (!seen.has(id)) { seen.add(id); continue; }

    // Duplicate: clear + regenerate
    sh.getRange(row, TASKID_CFG.COL_TASKID).clearContent();
    ensureTaskId_(sh, row);
  }
}
