const DATES_CFG = {
  SHEET_NAME: 'Daily Planner 2026',
  COL_DATE: 1,      // A
  COL_ACTIVITY: 4   // D
};

// Stamp Date when Activity is entered (handles paste of multiple rows too)
function dates_onEdit_(e) {
  const sh = e.range.getSheet();
  if (sh.getName() !== DATES_CFG.SHEET_NAME) return;

  const range = e.range;
  const startRow = range.getRow();
  const startCol = range.getColumn();
  const numRows = range.getNumRows();
  const numCols = range.getNumColumns();
  if (startRow < 2) return;

  const endCol = startCol + numCols - 1;
  const touchesActivity = (startCol <= DATES_CFG.COL_ACTIVITY && DATES_CFG.COL_ACTIVITY <= endCol);
  if (!touchesActivity) return;

  for (let r = startRow; r < startRow + numRows; r++) {
    const activity = (sh.getRange(r, DATES_CFG.COL_ACTIVITY).getValue() || '').toString().trim();
    if (!activity) continue;

    const dateCell = sh.getRange(r, DATES_CFG.COL_DATE);
    if (!dateCell.getValue()) dateCell.setValue(new Date());
  }
}

// Menu tool: fill blanks in Date using the most recent date above (only where Activity exists)
function fillDatesForward() {
  const sh = SpreadsheetApp.getActive().getSheetByName(DATES_CFG.SHEET_NAME);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return;

  let lastDate = null;

  for (let r = 2; r <= lastRow; r++) {
    const activity = (sh.getRange(r, DATES_CFG.COL_ACTIVITY).getValue() || '').toString().trim();
    if (!activity) continue;

    const cell = sh.getRange(r, DATES_CFG.COL_DATE);
    const v = cell.getValue();

    if (v instanceof Date) {
      lastDate = v;
      continue;
    }

    if (lastDate) cell.setValue(lastDate);
    else cell.setValue(new Date());
  }
}
